// Repair an npm package-lock.json whose entries are missing `resolved` and
// `integrity` (generated by an npm version affected by npm/cli#6301).
//
// npm itself refuses to fill these in incrementally (`npm install
// --package-lock-only` reports "up to date"), and regenerating from scratch
// would drift the locked versions. Instead we fill the two missing fields
// from the npm registry while preserving the exact locked versions:
//
//   - `resolved` is the registry tarball URL, fully determined by name+version
//   - `integrity` is the SRI hash of that tarball (immutable once published)
//
// Both are immutable for a published version, so the result is deterministic.
// This runs inside the fetchNpmDeps fixed-output derivation (which has
// network access); it must NOT run in the main build sandbox.
import { readFileSync, writeFileSync } from "node:fs";

const LOCKFILE = process.argv[2] ?? "package-lock.json";

const lock = JSON.parse(readFileSync(LOCKFILE, "utf8"));
const pk = lock.packages ?? {};

const missing = [];
for (const [key, value] of Object.entries(pk)) {
  if (!key.startsWith("node_modules/") || value.resolved || value.link) {
    continue;
  }
  if (!value.version) {
    continue;
  }
  // Prefer the real package name (npm aliases store it in `name`); for a
  // normal entry it is absent and we derive it from the last path segment
  // of the lockfile key (nested entries are `node_modules/a/node_modules/b`).
  missing.push({
    key,
    name: value.name ?? key.split("node_modules/").pop(),
    version: value.version,
  });
}

if (missing.length === 0) {
  process.stderr.write("repair-lockfile: nothing to do\n");
  process.exit(0);
}

process.stderr.write(
  `repair-lockfile: filling ${missing.length} entries missing resolved/integrity\n`,
);

// The registry packument URL uses the scoped form `@scope%2Fname`.
function packumentUrl(name, version) {
  const enc = name.replace("/", "%2F"); // keep the leading '@' literal
  return `https://registry.npmjs.org/${enc}/${version}`;
}

async function fetchWithRetry(url, attempts = 4) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      const res = await fetch(url, {
        headers: { accept: "application/json" },
        signal: AbortSignal.timeout(60_000),
      });
      if (res.ok) {
        return await res.json();
      }
      lastError = new Error(`HTTP ${res.status} for ${url}`);
    } catch (err) {
      lastError = err;
    }
    await new Promise((r) => setTimeout(r, 500 * 2 ** i));
  }
  throw lastError;
}

const failures = [];
let cursor = 0;
const workers = Array.from({ length: 24 }, async () => {
  while (cursor < missing.length) {
    const { key, name, version } = missing[cursor++];
    try {
      const data = await fetchWithRetry(packumentUrl(name, version));
      const dist = data?.dist;
      if (!dist?.tarball || !dist?.integrity) {
        throw new Error(`no dist metadata for ${name}@${version}`);
      }
      pk[key].resolved = dist.tarball.replace(/^http:\/\//, "https://");
      pk[key].integrity = dist.integrity;
    } catch (err) {
      failures.push(`${name}@${version} (${key}): ${err}`);
    }
  }
});
await Promise.all(workers);

if (failures.length > 0) {
  for (const f of failures) {
    process.stderr.write(`repair-lockfile: FAILED ${f}\n`);
  }
  process.stderr.write(
    `repair-lockfile: ${failures.length} entries could not be repaired\n`,
  );
  process.exit(1);
}

writeFileSync(LOCKFILE, JSON.stringify(lock, null, 2) + "\n");
process.stderr.write(
  `repair-lockfile: repaired ${missing.length} entries\n`,
);
